def direct(prim,sec,rot,operator):
 s=old
 for bank,chosen in [('primary',prim),('secondary',sec)]:
  if chosen:
   prev=f'((PathAttachmentSample *)((char *){bank}_samples + sample_offset))[-1].transform'
   nxt=f'((PathAttachmentSample *)((char *){bank}_samples + sample_offset))->transform'
   start=s.index('                orient_previous_with_fixed_right(\n                    previous_'+bank+',');end=s.index('));',start)+3
   delta=f'{nxt}.position - {prev}.position' if operator else 'Vector3('+',\n                    '.join(f'{nxt}.position.{c} - {prev}.position.{c}' for c in 'xyz')+')'
   new=f'''                {prev}.basis_right = Vector3(1.0f, 0.0f, 0.0f);
                {prev}.basis_forward = {delta};
                {prev}.basis_forward.Normalize();
                {prev}.basis_up.Cross({prev}.basis_forward, {prev}.basis_right);'''
   s=s[:start]+new+s[end:]
 if rot:
  for bank in ['primary','secondary']:
   s=s.replace(f'previous_{bank}->transform.RotIdentity();',f'((PathAttachmentSample *)((char *){bank}_samples + sample_offset))[-1].transform.RotIdentity();')
 # Remove unused pointer aliases in each branch only.
 blocks=s.split('            else')
 for bi,block in enumerate(blocks):
  for bank in ['primary','secondary']:
   if block.count('previous_'+bank)==1:
    declaration=re.search(r'                PathAttachmentSample \*previous_'+bank+r' =[\s\S]*?;',block).group()
    block=block.replace(declaration+'\n','',1)
  blocks[bi]=block
 s='            else'.join(blocks)
 return baseline[:a]+s+baseline[b:]
